<?php requirePermission('returns');$rows=$pdo->query('SELECT r.*,s.total sale_total,u.name user_name FROM sale_returns r JOIN sales s ON s.id=r.sale_id JOIN users u ON u.id=r.user_id ORDER BY r.id DESC LIMIT 100')->fetchAll();$title='Devoluções';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Devoluções e cancelamentos</h1><p>Histórico de estornos com retorno automático ao estoque.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>#</th><th>Venda</th><th>Tipo</th><th>Valor</th><th>Motivo</th><th>Operador</th><th>Data</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><a href="index.php?page=sale_view&id=<?=$r['sale_id']?>">#<?=$r['sale_id']?></a></td><td><?=e($r['type'])?></td><td><?=money($r['total'])?></td><td><?=e($r['reason'])?></td><td><?=e($r['user_name'])?></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../../includes/footer.php';?>
